package com.fernandaazevedo.support;
import com.fasterxml.jackson.databind.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.mock.web.MockHttpSession; import org.springframework.test.web.servlet.*; import java.util.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:support-test;DB_CLOSE_DELAY=-1","spring.jpa.hibernate.ddl-auto=create-drop"}) @AutoConfigureMockMvc
class SupportIntegrationTest {
 @Autowired MockMvc mvc; @Autowired ObjectMapper json;
 @Test void requesterCreatesAndSupportClaimsTicketWithRbac()throws Exception{Login patient=login("paciente@fernandaazevedo.demo"),support=login("suporte@fernandaazevedo.demo");var created=mvc.perform(post("/api/tickets").session(patient.session).header("X-CSRF-Token",patient.csrf).contentType("application/json").content(json.writeValueAsString(Map.of("subject","Minha câmera não iniciou","category","Câmera e microfone","priority","ALTA")))).andExpect(status().isCreated()).andExpect(jsonPath("$.ticketNumber").value(org.hamcrest.Matchers.startsWith("FA-"))).andReturn();long id=json.readTree(created.getResponse().getContentAsString()).get("id").asLong();mvc.perform(get("/api/tickets").session(patient.session)).andExpect(status().isOk()).andExpect(jsonPath("$[0].requesterName").value("João Almeida"));mvc.perform(post("/api/tickets/{id}/claim",id).session(patient.session).header("X-CSRF-Token",patient.csrf)).andExpect(status().isForbidden());mvc.perform(post("/api/tickets/{id}/claim",id).session(support.session).header("X-CSRF-Token",support.csrf)).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("IN_PROGRESS"));}
 @Test void internalNotesAreHiddenFromRequester()throws Exception{Login patient=login("paciente@fernandaazevedo.demo");var created=mvc.perform(post("/api/tickets").session(patient.session).header("X-CSRF-Token",patient.csrf).contentType("application/json").content("{\"subject\":\"Ajuda operacional\"}")).andReturn();long id=json.readTree(created.getResponse().getContentAsString()).get("id").asLong();mvc.perform(get("/api/tickets/{id}/messages",id).session(patient.session)).andExpect(status().isOk()).andExpect(jsonPath("$").isEmpty());}
 private Login login(String email)throws Exception{var r=mvc.perform(post("/api/auth/login").contentType("application/json").content(json.writeValueAsString(Map.of("email",email,"password","Demo@123")))).andExpect(status().isOk()).andReturn();return new Login((MockHttpSession)r.getRequest().getSession(false),json.readTree(r.getResponse().getContentAsString()).get("csrfToken").asText());} record Login(MockHttpSession session,String csrf){}
}
